import{_ as n,o as s,c as l,ae as e}from"./chunks/framework.CFyvOAXl.js";const b=JSON.parse('{"title":"系统设计专题","description":"","frontmatter":{},"headers":[],"relativePath":"program/interview/aiinfra_system_design.md","filePath":"program/interview/aiinfra_system_design.md","lastUpdated":1786894185000}'),i={name:"program/interview/aiinfra_system_design.md"};function p(r,a,t,o,c,u){return s(),l("div",null,[...a[0]||(a[0]=[e(`<h1 id="系统设计专题" tabindex="-1">系统设计专题 <a class="header-anchor" href="#系统设计专题" aria-label="Permalink to &quot;系统设计专题&quot;">​</a></h1><blockquote><p>首次编写：2026-08-12 | 最后更新：2026-08-12</p></blockquote><blockquote><p><strong>AI Infra / KV Cache 面试系列</strong></p><ul><li><a href="./aiinfra_overview.html">导读</a></li><li><a href="./aiinfra_jobs.html">招聘全景</a></li><li><a href="./aiinfra_kvcache_deep_dive.html">KV Cache 核心知识体系</a></li><li><a href="./aiinfra_interview_questions.html">面经与高频考点</a></li><li><strong>系统设计专题</strong> ← 当前文章</li><li><a href="./aiinfra_2month_plan.html">2 个月面试复习计划</a></li><li><a href="./aiinfra_resources.html">资源汇总</a></li></ul></blockquote><p>系统设计是 AI Infra 面试的<strong>决定性轮次</strong>。本文给出 4 道高频题的<strong>完整工作示例</strong>：需求澄清 -&gt; 架构图 -&gt; 核心组件 -&gt; 权衡 -&gt; 追问应对。每题配 ASCII 架构图，面试时可在白板画出。</p><p>技术原理见 <a href="./aiinfra_kvcache_deep_dive.html">KV Cache 核心知识体系</a>，题点见 <a href="./aiinfra_interview_questions.html">面经第 5 章</a>。</p><hr><h2 id="通用方法论-每题都按此结构" tabindex="-1">通用方法论（每题都按此结构） <a class="header-anchor" href="#通用方法论-每题都按此结构" aria-label="Permalink to &quot;通用方法论（每题都按此结构）&quot;">​</a></h2><ol><li><strong>澄清需求（2-3 min）</strong>：主动问清楚规模、SLO、模型、约束。别假设。</li><li><strong>估算（2 min）</strong>：算显存/带宽/QPS 量级，验证可行性。</li><li><strong>架构（8-10 min）</strong>：画图，讲数据流，点出核心组件。</li><li><strong>深挖核心组件（10 min）</strong>：调度、KV Cache、通信--这是区分度所在，结合本 Wiki 知识。</li><li><strong>权衡与追问（5 min）</strong>：延迟 vs 吞吐、成本 vs 质量、显存 vs 算力。主动给方案。</li></ol><blockquote><p>面试官最爱追问的不是&quot;是什么&quot;而是&quot;为什么这样选 / 还有什么方案 / 极限在哪&quot;。每个选择都准备 Plan B。</p></blockquote><hr><h2 id="题-1-设计高并发-llm-推理服务-端到端-⭐⭐⭐⭐⭐" tabindex="-1">题 1：设计高并发 LLM 推理服务（端到端）⭐⭐⭐⭐⭐ <a class="header-anchor" href="#题-1-设计高并发-llm-推理服务-端到端-⭐⭐⭐⭐⭐" aria-label="Permalink to &quot;题 1：设计高并发 LLM 推理服务（端到端）⭐⭐⭐⭐⭐&quot;">​</a></h2><h3 id="_1-1-需求澄清" tabindex="-1">1.1 需求澄清 <a class="header-anchor" href="#_1-1-需求澄清" aria-label="Permalink to &quot;1.1 需求澄清&quot;">​</a></h3><ul><li><strong>规模</strong>：峰值 QPS 1000，平均输入 1K token，平均输出 500 token。</li><li><strong>SLO</strong>：TTFT P99 &lt; 1s，TPOT &lt; 50ms。</li><li><strong>模型</strong>：70B（fp8 权重）+ GQA。</li><li><strong>约束</strong>：单集群 H100-80G，成本敏感，多租户。</li></ul><h3 id="_1-2-估算" tabindex="-1">1.2 估算 <a class="header-anchor" href="#_1-2-估算" aria-label="Permalink to &quot;1.2 估算&quot;">​</a></h3><ul><li>权重：70B × 1 byte(fp8) ≈ 70GB，单卡放不下，需 TP=2（每卡 35GB）。</li><li>KV Cache（GQA，n_kv=8, L=80, d_h=128, fp8）：单 token = 2×80×8×128×1 = 160KB。</li><li>单请求 KV：1K+500 token ≈ 1.5K × 160KB ≈ 240MB。</li><li>峰值并发：QPS 1000 × (prefill 1s + decode 500×50ms=25s) ≈ 在途请求巨大，纯 decode 并发 ~26000 条 -&gt; KV 需 ~6.2TB。<strong>显然单机不行，必须分布式 + PD 分离 + KV 复用。</strong></li></ul><blockquote><p>估算的目的不是精确，是暴露&quot;单机不可行&quot;并引出分布式架构。</p></blockquote><h3 id="_1-3-架构" tabindex="-1">1.3 架构 <a class="header-anchor" href="#_1-3-架构" aria-label="Permalink to &quot;1.3 架构&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌───────────────────────────┐</span></span>
<span class="line"><span>                    │     Gateway / LB / 鉴权    │</span></span>
<span class="line"><span>                    └─────────────┬─────────────┘</span></span>
<span class="line"><span>                                  │</span></span>
<span class="line"><span>                    ┌─────────────▼─────────────┐</span></span>
<span class="line"><span>                    │   Router / Scheduler       │</span></span>
<span class="line"><span>                    │ (请求路由, 优先级, 限流)    │</span></span>
<span class="line"><span>                    └──┬─────────────────────┬───┘</span></span>
<span class="line"><span>                       │                     │</span></span>
<span class="line"><span>            ┌──────────▼─────────┐ ┌─────────▼───────────┐</span></span>
<span class="line"><span>            │  Prefill 池 (TP=2) │ │  Decode 池 (TP=2)    │</span></span>
<span class="line"><span>            │  compute-bound     │ │  memory-bound        │</span></span>
<span class="line"><span>            │  chunked prefill   │ │  大batch连续批处理   │</span></span>
<span class="line"><span>            │  产出 KV           │ │  逐token生成         │</span></span>
<span class="line"><span>            └──────────┬─────────┘ └─────────▲───────────┘</span></span>
<span class="line"><span>                       │    KV 传输(RDMA/压缩)│</span></span>
<span class="line"><span>                       └──────────────────────┘</span></span>
<span class="line"><span>                                  │</span></span>
<span class="line"><span>                    ┌─────────────▼─────────────┐</span></span>
<span class="line"><span>                    │   全局 KV Cache 池         │</span></span>
<span class="line"><span>                    │ (前缀复用/会话复用/分层)   │</span></span>
<span class="line"><span>                    │  HBM ⇄ DRAM ⇄ SSD         │</span></span>
<span class="line"><span>                    └───────────────────────────┘</span></span>
<span class="line"><span>                                  │</span></span>
<span class="line"><span>                    ┌─────────────▼─────────────┐</span></span>
<span class="line"><span>                    │  权重存储 / 监控 / 计费    │</span></span>
<span class="line"><span>                    └───────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br></div></div><h3 id="_1-4-核心组件深挖" tabindex="-1">1.4 核心组件深挖 <a class="header-anchor" href="#_1-4-核心组件深挖" aria-label="Permalink to &quot;1.4 核心组件深挖&quot;">​</a></h3><ul><li><strong>PD 分离</strong>：prefill 池 compute-bound 配高算力，decode 池 memory-bound 配大显存/带宽。prefill 算完 KV 通过 RDMA 传给 decode 池（MLA/量化压缩 KV 减传输量，与 decode 首步 overlap）。</li><li><strong>调度器</strong>：decode 池用连续批处理 + 优先级 + 抢占（低优先级 KV swap 出）；prefill 池用 chunked prefill 避免 long prompt 卡 decode。</li><li><strong>KV Cache 池</strong>：PagedAttention 分页 + 前缀缓存（system prompt/文档复用）+ 量化 fp8 + 分层卸载（活跃 KV 在 HBM，冷 KV 在 DRAM/SSD）。全局池使会话多轮/多用户同文档命中即跳 prefill。</li><li><strong>多租户</strong>：显存配额 + KV 隔离 + 优先级队列 + 公平调度，防大客户饿死小客户。</li></ul><h3 id="_1-5-权衡与追问" tabindex="-1">1.5 权衡与追问 <a class="header-anchor" href="#_1-5-权衡与追问" aria-label="Permalink to &quot;1.5 权衡与追问&quot;">​</a></h3><ul><li>&quot;TTFT 怎么降？&quot; -&gt; chunked prefill + prefill 池独立 + KV 复用命中跳过 prefill。</li><li>&quot;显存不够？&quot; -&gt; 量化(KV fp8/int4) + 卸载分层 + PD 分离按画像配比 + 前缀复用减总量。</li><li>&quot;成本？&quot; -&gt; 大 batch 提利用率 + PD 分离 + 投机解码减步数 + 弹性扩缩。</li><li>&quot;故障？&quot; -&gt; decode 实例滚动替换，KV 池持久化会话 KV 可恢复；权重热加载。</li><li>&quot;为什么不用纯 TP 大集群一个模型？&quot; -&gt; TP 通信随卡数线性增，过大通信主导；PD 分离 + 池化更灵活。</li></ul><hr><h2 id="题-2-设计-kv-cache-池化服务-mooncake-风格-⭐⭐⭐⭐⭐" tabindex="-1">题 2：设计 KV Cache 池化服务（Mooncake 风格）⭐⭐⭐⭐⭐ <a class="header-anchor" href="#题-2-设计-kv-cache-池化服务-mooncake-风格-⭐⭐⭐⭐⭐" aria-label="Permalink to &quot;题 2：设计 KV Cache 池化服务（Mooncake 风格）⭐⭐⭐⭐⭐&quot;">​</a></h2><h3 id="_2-1-需求澄清" tabindex="-1">2.1 需求澄清 <a class="header-anchor" href="#_2-1-需求澄清" aria-label="Permalink to &quot;2.1 需求澄清&quot;">​</a></h3><ul><li>多用户共享同一批文档/会话，最大化 KV 复用。</li><li>单文档可达 100K+ token，复用价值高。</li><li>低 QPS 但长上下文，prefill 成本高。</li></ul><h3 id="_2-2-架构" tabindex="-1">2.2 架构 <a class="header-anchor" href="#_2-2-架构" aria-label="Permalink to &quot;2.2 架构&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   请求 ──► 前缀匹配 ──► 命中?</span></span>
<span class="line"><span>                │ 是            │ 否</span></span>
<span class="line"><span>                ▼               ▼</span></span>
<span class="line"><span>          从 KV 池取 KV     Prefill 计算 ──► 写入 KV 池</span></span>
<span class="line"><span>                │               │</span></span>
<span class="line"><span>                └──► Decode（复用/新增 KV）──► 更新池</span></span>
<span class="line"><span>                                          │</span></span>
<span class="line"><span>                          ┌───────────────▼───────────────┐</span></span>
<span class="line"><span>                          │   全局 KV Cache 池（分层索引）  │</span></span>
<span class="line"><span>                          │  前缀树 / hash -&gt; KV 位置       │</span></span>
<span class="line"><span>                          │  HBM(热) ⇄ DRAM(温) ⇄ SSD(冷)  │</span></span>
<span class="line"><span>                          │  LRU + 引用计数 + COW           │</span></span>
<span class="line"><span>                          └───────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h3 id="_2-3-核心设计" tabindex="-1">2.3 核心设计 <a class="header-anchor" href="#_2-3-核心设计" aria-label="Permalink to &quot;2.3 核心设计&quot;">​</a></h3><ul><li><strong>索引</strong>：Radix Tree（前缀 token 序列 -&gt; KV 块位置），共享前缀共享节点，引用计数。</li><li><strong>分层存储</strong>：热 KV 在 HBM，温在 DRAM，冷在 SSD；按访问频率迁移；预取与 decode overlap。</li><li><strong>复用粒度</strong>：块级（PagedAttention block），命中整段前缀直接复用 KV、跳过该段 prefill。</li><li><strong>淘汰</strong>：LRU + 引用计数（共享节点不被误删）+ 容量水位触发淘汰。</li><li><strong>一致性</strong>：copy-on-write--某请求要&quot;分叉&quot;生成不同 token 时，复制该块再写，不影响其他引用者。</li><li><strong>传输</strong>：MLA latent / 量化 KV 减传输量；RDMA 直传 decode 实例。</li></ul><h3 id="_2-4-追问" tabindex="-1">2.4 追问 <a class="header-anchor" href="#_2-4-追问" aria-label="Permalink to &quot;2.4 追问&quot;">​</a></h3><ul><li>&quot;命中率不高时怎么办？&quot; -&gt; 池是开销（占内存 + 索引维护），命中率低时收益为负。需动态评估：命中率低于阈值则退化为不池化或缩小池。</li><li>&quot;池容量怎么规划？&quot; -&gt; 按&quot;热点文档/会话总 KV 量 × 命中预期&quot;估，分层让冷数据下沉到便宜的 SSD。</li><li>&quot;多实例一致性？&quot; -&gt; 全局索引 + KV 块不可变（写时复制），避免复杂一致性；跨实例只读共享。</li><li>&quot;KV 池故障？&quot; -&gt; 命中失效退化为重新 prefill（可接受，非数据丢失）；索引持久化可加速恢复。</li></ul><hr><h2 id="题-3-把一个-mla-moe-新模型接入推理引擎-⭐⭐⭐⭐" tabindex="-1">题 3：把一个 MLA + MoE 新模型接入推理引擎 ⭐⭐⭐⭐ <a class="header-anchor" href="#题-3-把一个-mla-moe-新模型接入推理引擎-⭐⭐⭐⭐" aria-label="Permalink to &quot;题 3：把一个 MLA + MoE 新模型接入推理引擎 ⭐⭐⭐⭐&quot;">​</a></h2><h3 id="_3-1-步骤" tabindex="-1">3.1 步骤 <a class="header-anchor" href="#_3-1-步骤" aria-label="Permalink to &quot;3.1 步骤&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模型结构分析 ──► 权重转换/分片 ──► attention kernel 适配</span></span>
<span class="line"><span>      │                                  │</span></span>
<span class="line"><span>      ▼                                  ▼</span></span>
<span class="line"><span>  MoE 路由实现 ◄───────────────── 调度器/KV 布局适配</span></span>
<span class="line"><span>      │                                  │</span></span>
<span class="line"><span>      └────────► 量化支持 ──► benchmark 验证 ──► 上线</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="_3-2-关键点" tabindex="-1">3.2 关键点 <a class="header-anchor" href="#_3-2-关键点" aria-label="Permalink to &quot;3.2 关键点&quot;">​</a></h3><ul><li><strong>MLA 适配</strong>：不能当普通 KV。需 latent cache 专用 kernel（上投影 c_KV-&gt;K/V + 解耦 RoPE 拼接）；调度器管理 latent 而非 K/V；TP 切分按 latent 维度调整。对照作者 <a href="./../kvcache/sglang_glm52_attention_mechanism.html">GLM-5.2 Attention 机制</a>。</li><li><strong>MoE 适配</strong>：attention 仍 dense（KV Cache 正常），但 FFN 是专家路由。需 expert routing kernel + EP 通信（all-to-all）+ 负载均衡处理。权重显存大头是专家。</li><li><strong>权重分片</strong>：TP 切 attention 头 + latent；EP 切专家；PP 切层。三者组合。</li><li><strong>量化</strong>：权重 W8A8/FP8 + KV fp8（MLA 量化 latent）。</li><li><strong>验证</strong>：精度（对比 transformers 参考）+ 性能（Nsight profile kernel，对比基线）。</li></ul><h3 id="_3-3-追问" tabindex="-1">3.3 追问 <a class="header-anchor" href="#_3-3-追问" aria-label="Permalink to &quot;3.3 追问&quot;">​</a></h3><ul><li>&quot;MLA 的 TP 切分和普通 attention 有什么不同？&quot; -&gt; 普通 TP 切头，MLA 要切 latent 维度且保证上投影矩阵对齐，RoPE 部分单独处理。</li><li>&quot;MoE 的显存瓶颈？&quot; -&gt; 专家权重（激活稀疏但权重全驻留），用 EP 分布到多卡；KV Cache 仍按 attention 算。</li><li>&quot;MLA 在分离式推理下是优势还是劣势？&quot; -&gt; 优势：传输的是 latent（小），跨实例 KV 搬运量大幅减少。</li></ul><hr><h2 id="题-4-优化线上推理成本-⭐⭐⭐⭐" tabindex="-1">题 4：优化线上推理成本 ⭐⭐⭐⭐ <a class="header-anchor" href="#题-4-优化线上推理成本-⭐⭐⭐⭐" aria-label="Permalink to &quot;题 4：优化线上推理成本 ⭐⭐⭐⭐&quot;">​</a></h2><h3 id="_4-1-杠杆点-按收益排序" tabindex="-1">4.1 杠杆点（按收益排序） <a class="header-anchor" href="#_4-1-杠杆点-按收益排序" aria-label="Permalink to &quot;4.1 杠杆点（按收益排序）&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>提利用率        ──►  连续批处理 / 大 batch / PD 分离按画像配比</span></span>
<span class="line"><span>减重算          ──►  前缀缓存 / RadixAttention / KV 池复用</span></span>
<span class="line"><span>减访存/显存     ──►  KV 量化(fp8/int4) / 权重量化 / 卸载分层</span></span>
<span class="line"><span>减串行步数      ──►  投机解码 / PD 分离</span></span>
<span class="line"><span>弹性            ──►  峰谷扩缩 / spot / 性价比芯片</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_4-2-量化收益" tabindex="-1">4.2 量化收益 <a class="header-anchor" href="#_4-2-量化收益" aria-label="Permalink to &quot;4.2 量化收益&quot;">​</a></h3><ul><li>连续批处理 + PD 分离：goodput 提升 2-4x（典型）。</li><li>前缀复用：命中场景 prefill 成本近归零（多轮/同文档）。</li><li>KV fp8：显存与带宽 2x，decode 吞吐 1.5-2x。</li><li>投机解码：accept rate 高时步数减半。</li><li>权重 INT4/FP8：显存 2-4x，可上更大 batch 或更小卡。</li></ul><h3 id="_4-3-追问" tabindex="-1">4.3 追问 <a class="header-anchor" href="#_4-3-追问" aria-label="Permalink to &quot;4.3 追问&quot;">​</a></h3><ul><li>&quot;哪个优化先做？&quot; -&gt; 先连续批处理 + 前缀复用（收益大、改动小），再量化，再 PD 分离（改动大、收益大）。</li><li>&quot;量化精度掉了怎么办？&quot; -&gt; 敏感层保留高精度 + per-channel/FP8 + 评测对齐。</li><li>&quot;投机解码什么时候不划算？&quot; -&gt; draft 接受率低、prefill 占比高、算力已打满时。</li></ul><hr><h2 id="系统设计练习清单-自练" tabindex="-1">系统设计练习清单（自练） <a class="header-anchor" href="#系统设计练习清单-自练" aria-label="Permalink to &quot;系统设计练习清单（自练）&quot;">​</a></h2><p>每题限时 30min，画图 + 讲解，录音复盘：</p><ol><li>设计支持百万 token 上下文的推理服务。</li><li>设计多模态（图+文）LLM 推理服务。</li><li>设计多 LoRA 适配器的 serving 服务。</li><li>设计跨地域的 LLM 推理平台（容灾 + 低延迟）。</li><li>设计一个推理引擎的调度器（优先级 + 抢占 + 显存）。</li></ol><blockquote><p>把每题的架构图存档，面试前快速过一遍。系统设计能力 = 练过的题量 × 反思深度。</p></blockquote><hr><p>下一篇：<a href="./aiinfra_2month_plan.html">2 个月面试复习计划</a>。</p>`,55)])])}const d=n(i,[["render",p]]);export{b as __pageData,d as default};
